package core

import "appfactory/internal/protocol"

// runtimeInstructions is the provider-neutral Factory MCP contract appended to a run's
// developer instructions. Core serves it with the run credential so every Worker uses one text.
// exitInstructions are added to the run instructions while explicit exits are on.
const exitInstructions = "Explicit exits: end every run with exactly one factory_exit_* call, then finish the turn: submit (for review; commit first, the tree must be clean), handoff (to another agent or yourself; reviewers give verdict approved or changes_requested), done (finished; a code task needs its pull request merged first), ask (a question you cannot continue without), block (until other tasks or your children are done) or wait (until a time). A refused exit explains why: fix it and exit again. Tool results may carry authority_input (directives from the owner or managers): act on it before exiting; the smallest rank wins on conflict. A 410 answer means the run was stopped: finish the turn.\n"

func runtimeInstructions(spec protocol.RunSpec) string {
	return "\nFactory MCP is available as server factory. Use its tools for project/task operations and lazy skill reads. Identity and project are bound to this run; do not supply actor or project_id. Mutations require a stable request_id and the latest entity version. On transport uncertainty, reuse the SAME request_id and arguments; do not repeat side effects with a new key. A 423 response requires owner approval: use factory_owner_request_approval with the exact tool name and original arguments including request_id and version. For a blocking request finish this turn immediately; Core resumes after a decision. Read factory_approval_get before retrying, and proceed only if APPROVED. Rejection, expiry and ordinary chat answers never authorize an action. Changing arguments requires a new approval. Artifact versions can be registered with factory_artifact_register and approved separately with factory_artifact_request_approval; a task submission does not approve an artifact. Downstream tasks declare required_artifacts with exact id/version/URI. Use the owner-approved artifact inputs pinned in your run prompt. OpenSpec documents live in the project workspace: use factory_openspec_list/read/check for current requirements. Read a linked change and relevant specs before implementing it. Factory checks references; use official OpenSpec tools for schema/semantic validation and archive. Markdown checkboxes do not change task status. A structured submission does not finish or accept a task. Read approved project decisions before repeating an owner question; use decision_get for full records and decision_list for current versions. Decision proposals are not approvals or tool permissions; decision_record requires exact owner authorization. Reports record significant actions; a needs_owner_action report creates an inbox notice without blocking this turn.\n" +
		"Current Factory message: " + spec.MessageID + "; run: " + spec.ID + "; task: " + spec.TaskID + "; agent: " + spec.Agent + "; project: " + spec.Project + ".\n"
}
